import{z as i,x as o,o as A,c as p,q as l,j as t,D as e,d as B,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"阿莱悖论与独立性","description":"","frontmatter":{"title":"阿莱悖论与独立性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/allais-independence.md","filePath":"econ/allais-independence.md","lastUpdated":1791413859000}'),d={name:"econ/allais-independence.md"};function m(u,a,h,C,c,b){const n=o("Mermaid");return A(),p("div",null,[a[2]||(a[2]=l('<h1 id="阿莱悖论与独立性" tabindex="-1">阿莱悖论与独立性 <a class="header-anchor" href="#阿莱悖论与独立性" aria-label="Permalink to &quot;阿莱悖论与独立性&quot;">​</a></h1><div class="epigraph"><p>共同结果从两张彩票里同时删去之后，排序仍应保持——可实验里同一批人会把这道算术做错。</p><footer>—— 据 Allais, Le comportement de l&#39;homme rationnel devant le risque, Econometrica, 1953 整理</footer></div><p><a href="/econ/vnm-axioms">上一课</a>（vNM 公理怎么用）。用独立性推出 \\(U(F)=\\mathbb{E}_F u\\)。本课不重讲表示定理，也不另起一套彩票符号。缺口是：独立性在复合彩票上意味着共同混合项可以消掉，但 Allais 的问卷让相当一部分人留下共同项、改变排序。主干仍用期望效用，必须先标明这条公理哪里脆，后课 Arrow–Pratt 才知道自己站在哪一块石头上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>取 Allais 的经典四张彩票。\\(A\\) 确定得到一笔中奖；\\(B\\) 以高概率得到更多、以小概率得到零。另一对 \\(A&#39;\\)、\\(B&#39;\\) 是把前一对里共同的那个结果换成零。独立性要求 \\(A\\succsim B\\) 当且仅当 \\(A&#39;\\succsim B&#39;\\)，因为两对之差只是同一个共同结果被加进或拿掉。许多人选 \\(A\\) 而选 \\(B&#39;\\)：确定效应让人在第一对里躲开零的可能，第二对里零已经是常态，又去追高期望。</p><p><span class="marginnote">数字实例：经典版本用百万计——\\(A\\)：确定得 100 万；\\(B\\)：0.10 得 500 万、0.89 得 100 万、0.01 得 0。\\(A&#39;\\)：0.11 得 100 万；\\(B&#39;\\)：0.10 得 500 万。大量受试者选 \\(A\\) 又选 \\(B&#39;\\)——可 \\(A&#39;\\) 与 \\(B&#39;\\) 恰是 \\(A\\)、\\(B\\) 把共同的那 0.89 概率的 100 万一并换成零所得。排序翻转，独立性被当场打掉。</span></p><p>缺口因此不是「人不会算期望」，而是：<strong>共同结果独立性在描述上失败</strong>。若把失败写成新理论，后课的凹伯努利函数、随机占优都要改写。本栏选择：把阿莱当边界对照，主干继续用 \\(\\mathbb{E}u\\)，但禁止后课假装独立性从未被质疑。</p><h3 id="共同结果与共同比率是同一公理的两面" tabindex="-1">共同结果与共同比率是同一公理的两面 <a class="header-anchor" href="#共同结果与共同比率是同一公理的两面" aria-label="Permalink to &quot;共同结果与共同比率是同一公理的两面&quot;">​</a></h3><p>共同比率效应把概率按同一因子缩小，独立性同样要求排序不变。经验上它与共同结果一起出现。Machina 的局部期望效用、Chew 的加权效用、Quiggin 的秩依赖，都是放松独立性而保留一阶随机占优之类的弱性质。本课不展开这些表示，只指出：放松点是独立性，不是完备传递。</p><p><span class="marginnote">确定性的 \\(1\\) 与概率 \\(0.99\\) 在 vNM 里只差一个仿射刻度上的小权重。阿莱显示人把「确定」当成质变。这是对线性概率权重的打击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把独立性写成：比较 \\(F\\) 与 \\(G\\) 时，把二者同时与 \\(H\\) 混合，排序不变。阿莱构造的是特别的 \\(H\\)——一大块共同的零，或一大块共同的确定中奖。检验只需两对选择，不必估计 \\(u\\)。这与显示偏好课的 WARP 同类：成对观测直接打公理，不经过参数。</p><p>若坚持 vNM，只能说受试者「算错」或问卷框架不稳定。若放弃 vNM，下一条仍常用的弱化是：一阶随机占优保留、介于独立与完全非线性之间。后课随机占优会在期望效用内部叙述；它也可以在更弱的单调性下叙述，那是边界。</p><p><span class="marginnote">常见误区：看到「独立性公理」，别联想到概率论里的「独立事件」——两者毫无关系，纯属中文译名撞车。这条公理说的是「往两张彩票里灌同一坛子水（混合同一个共同结果），不改变谁更好」，是偏好的性质，不是分布的性质。</span></p>',14)),(A(),t(s,null,{default:e(()=>[r(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22vNM%EF%BC%9A%E7%8B%AC%E7%AB%8B%E6%80%A7%22%5D%20--%3E%20CR%5B%22%E5%85%B1%E5%90%8C%E7%BB%93%E6%9E%9C%E5%BA%94%E5%8F%AF%E6%B6%88%E5%8E%BB%22%5D%0A%20%20CR%20--%3E%20ALLAIS%5B%22%E9%98%BF%E8%8E%B1%EF%BC%9A%E7%A1%AE%E5%AE%9A%E6%95%88%E5%BA%94%22%5D%0A%20%20ALLAIS%20--%3E%20KEEP%5B%22%E4%B8%BB%E5%B9%B2%E4%BB%8D%E7%94%A8%20E%20u%22%5D%0A%20%20ALLAIS%20--%3E%20DROP%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E7%A7%A9%E4%BE%9D%E8%B5%96%E7%AD%89%22%5D%0A%20%20KEEP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E6%B5%8B%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"问卷里的钱通常很小，把「确定一百万」换成「确定十块」时，确定效应往往仍在，只是强度变。这提醒：阿莱打的是权重的线性，不是奖金额的凹性。本课不估计一个 \\(u\\) 去拟合四张表。",-1)),a[4]||(a[4]=E("p",null,"本课不把前景理论写成新主干。概率扭曲、损失参照是另一条文献；货币理论与资产定价课默认仍是 \\(\\mathbb{E}u\\)。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"独立性失败的机制是「确定」与「几乎确定」不对齐线性权重，以及共同尾事件并未被决策者心理消掉。vNM 的证明把无差异概率当效用，正是假定这些权重可加减。阿莱等于说：无差异概率在不同共同项背景下不一致，伯努利函数随问卷变，表示崩溃。",-1)),(A(),t(s,null,{default:e(()=>[r(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E7%AC%AC%E4%B8%80%E5%AF%B9%3A%20A%20%E7%A1%AE%E5%AE%9A%E4%B8%AD%E5%A5%96%20vs%20B%20%E5%8F%AF%E8%83%BD%E5%BE%97%E9%9B%B6%22%5D%20--%3E%20C1%5B%22%E8%AE%B8%E5%A4%9A%E4%BA%BA%E9%80%89%20A%3A%20%E8%8A%B1%E5%A4%A7%E4%BB%B7%E9%92%B1%E8%BA%B2%E5%BC%80%E5%B0%8F%E6%A6%82%E7%8E%87%E9%9B%B6%22%5D%0A%20%20MIX%5B%22%E7%AC%AC%E4%BA%8C%E5%AF%B9%E6%8A%8A%E5%85%B1%E5%90%8C%E7%9A%84%200.89%20%E6%A6%82%E7%8E%87%20100%20%E4%B8%87%E6%8D%A2%E6%88%90%E9%9B%B6%22%5D%20--%3E%20P2%5B%22%E7%AC%AC%E4%BA%8C%E5%AF%B9%3A%20A%E6%92%87%20vs%20B%E6%92%87%22%5D%0A%20%20P2%20--%3E%20C2%5B%22%E8%AE%B8%E5%A4%9A%E4%BA%BA%E6%94%B9%E9%80%89%20B%E6%92%87%3A%20%E9%9B%B6%E5%B7%B2%E6%88%90%E5%B8%B8%E6%80%81%2C%20%E8%BD%AC%E8%80%8C%E8%BF%BD%E9%AB%98%E5%A5%96%22%5D%0A%20%20C1%20--%3E%20V%5B%22%E5%90%8C%E4%B8%80%E6%89%B9%E4%BA%BA%E6%8E%92%E5%BA%8F%E7%BF%BB%E8%BD%AC%3A%20%E8%BF%9D%E8%83%8C%E7%8B%AC%E7%AB%8B%E6%80%A7%22%5D%0A%20%20C2%20--%3E%20V%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：确定效应像「煮熟的鸭子」——99% 与 100% 到手之间的心理距离，远大于 60% 与 61%。所以人愿意为把 0.01 的零抹掉付出不成比例的代价；可一旦零本来就是大概率背景，这点刺眼感就消失了，权重又显出非线性的另一副面孔。</span></p><p>对后课的含义是双层的。规范层：若接受独立性作为理性要求，阿莱是偏差，保险与最优风险分担公式仍按 \\(\\mathbb{E}u\\) 写。描述层：若要拟合问卷，不要用同一 \\(u\\) 去硬套四张彩票。本栏宏观与公司金融走规范层；问卷本身不当成拒绝保险理论的充分统计。</p><p><span class="marginnote">Allais 原文针对的是 Savage 与 vNM 当时的确定性等价讨论，不是后来的前景理论。引用时不要把 1953 年的悖论写成 Kahneman–Tversky 的附录。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>实验室彩票的钱小、概率刻度被画在纸上，与市场里的保险、组合选择不是同一菜单。市场数据较少直接复制阿莱四张表。因此主干保留期望效用，不是无视实验，而是对象不同：后课 Arrow–Pratt、随机占优、或有要求权都在市场与理论内部使用 \\(\\mathbb{E}u\\)。</p><p>也不要把阿莱读成「人喜欢风险」。同一批人在第一对里表现得极度厌恶零结果，在第二对里又去追尾。这是独立性失败，不是凹性失败。凹性是下一课在 vNM 内部的缺口。</p><p>Ellsberg 打的是未知概率，不是已知概率上的线性。本课序不把模糊引进主干。保险与资产定价后课若改用秩依赖，必须显式声明；默认仍是期望。</p><p>后课默认：工作表示仍是 \\(\\mathbb{E}u\\)；写风险厌恶时不再回头论证独立性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>独立性要求共同混合项不改变排序；阿莱问卷系统违背这一点。</li><li>失败打在线性概率权重上，不是打在完备传递上。</li><li>本栏主干仍用期望效用，把阿莱当描述对照。</li><li>下一课在 vNM 内部测度凹性，不把悖论改写成「喜欢风险」。</li><li>出处：Allais, <em>Econometrica</em>, 1953；von Neumann and Morgenstern, 1944；Mas-Colell, Whinston and Green 第 6 章。</li></ul>',10))])}const _=i(d,[["render",m]]);export{f as __pageData,_ as default};
